action.command:
printf '%s\n' 'Configuration sections and key names:'; awk '
/^[[:space:]]*\[/ {gsub(/^[[:space:]]+|[[:space:]]+$/, ""); print "[section] " $0; next}
/^[[:space:]]*[A-Za-z_][A-Za-z0-9_.-]*[[:space:]]*=/ {line=$0; sub(/^[[:space:]]*/, "", line); sub(/[[:space:]]*=.*/, "", line); print "[key] " line}
' app_config.ini; printf '%s\n' 'Repository status:'; git status --short

